import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    private static long normalize(long angle) {
        long res = angle % 360;
        if (res < 0) res += 360;
        return res;
    }

    private static long deviation(long angle) {
        angle = normalize(angle);
        return Math.min(angle, 360 - angle);
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;
        long x = Long.parseLong(line.trim());

        long bestDeviation = Long.MAX_VALUE;
        int bestTurns = 0;

        for (int k = 0; k < 4; k++) {
            long totalRotation = x + 90L * k;
            long dev = deviation(totalRotation);
            if (dev < bestDeviation) {
                bestDeviation = dev;
                bestTurns = k;
            }
        }

        System.out.println(bestTurns);
    }
}

