public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong(); // camera angle in degrees, clockwise positive

        // Image is rotated opposite to camera: -x
        long base = ((-x) % 360 + 360) % 360; // normalize to [0, 359]

        int bestK = 0;
        long bestDev = 360; // larger than any possible deviation

        for (int k = 0; k < 4; k++) {
            long total = (base + 90L * k) % 360;
            long dev = Math.min(total, 360 - total);
            if (dev < bestDev) {
                bestDev = dev;
                bestK = k;
            }
        }

        System.out.println(bestK);
    }
}

