public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong(); // camera angle in degrees, clockwise positive

        // Image rotation relative to true up is -x (since camera CW => image CCW)
        // We can rotate image additionally by k * 90 degrees clockwise, k = 0..3
        // Total image angle = -x + 90*k (clockwise positive)
        // Deviation from vertical is minimal absolute angle modulo 360
        long bestK = 0;
        long bestDev = Long.MAX_VALUE;

        for (int k = 0; k < 4; k++) {
            long angle = -x + 90L * k; // total clockwise angle
            long mod = angle % 360;
            if (mod < 0) mod += 360;
            long dev = Math.min(mod, 360 - mod);
            if (dev < bestDev) {
                bestDev = dev;
                bestK = k;
            }
        }

        System.out.println(bestK);
    }
}

