import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong(); // camera angle in degrees, clockwise positive

        // Image rotation relative to "true up" is opposite of camera rotation
        // so initial image angle is -x degrees (clockwise positive).
        long initial = -x;

        int bestK = 0;
        long bestDev = Long.MAX_VALUE;

        for (int k = 0; k < 4; k++) {
            long angle = initial + 90L * k; // total clockwise rotation
            long norm = ((angle % 360) + 360) % 360; // normalize to [0, 360)
            long dev = Math.min(norm, 360 - norm);   // minimal deviation from vertical

            if (dev < bestDev) {
                bestDev = dev;
                bestK = k;
            }
        }

        System.out.println(bestK);
    }
}
